import { lazy } from 'react';
import { FileText as IcFileText, MapPin as IcMapPin, Users as IcUsers } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Visit Reports — hub page for the Travel Desk menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 2 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'TravelVisits'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const VisitReports = lazy(() => import('./VisitReports'));
const CustomerVisits = lazy(() => import('./CustomerVisits'));

export const TABS = [
  { id: 'reports', label: 'Visit Reports', icon: IcFileText, page: 'VisitReports', Component: VisitReports },
  { id: 'customers', label: 'Customer Visits', icon: IcUsers, page: 'CustomerVisits', Component: CustomerVisits },
];

export default function TravelVisits({ setPage }) {
  return (
    <TabHub
      icon={IcMapPin}
      eyebrow="Travel Desk"
      title="Visit Reports"
      subtitle="Trip reports and the customer visits they cover"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
